import {
  Component, ElementRef, TemplateRef, afterRenderEffect, computed, effect, inject, input, model, output, signal,
} from '@angular/core';
import { NgTemplateOutlet } from '@angular/common';
import { CdkDropList, CdkDrag, CdkDragHandle, CdkDragDrop, moveItemInArray } from '@angular/cdk/drag-drop';
import { NzTableModule, NzTableSize } from 'ng-zorro-antd/table';
import { NzTooltipDirective } from 'ng-zorro-antd/tooltip';
import { NzDropDownModule } from 'ng-zorro-antd/dropdown';
import { NzMenuModule } from 'ng-zorro-antd/menu';
import {
  TablerIconComponent, IconGripVertical, IconDotsVertical, IconSelector,
  IconArrowUp, IconArrowDown, IconColumns, IconEye, IconEyeOff, IconPinned, IconPinnedOff,
  IconChevronDown, IconChevronRight,
} from '@tabler/icons-angular';
import { HrmRowGroupLevel } from './hrm-data-config.types';

export interface HrmGridColumn {
  key: string;
  title: string;
  width?: string;
  align?: 'left' | 'center' | 'right';
  /** Bật sắp xếp client-side theo cột này (mũi tên trên tiêu đề). */
  sortable?: boolean;
  /** Ghim cột khi bảng cuộn ngang: 'right' (dính mép phải, VD cột thao tác) | 'left'. Cần minWidth/scroll.x. */
  fixed?: 'left' | 'right';
  /** Cột tính toán (giá trị suy từ công thức) — loại khỏi nhóm dữ liệu / sắp xếp. */
  computed?: boolean;
  /** Thuộc NHÓM CỘT nào (id) — render header 2 tầng: tiêu đề nhóm span các cột cùng groupId liền kề. */
  groupId?: string;
  /** Cho phép ẩn cột từ menu ⋯ / nút "Cột" (chỉ khi [customizable]). Mặc định true.
   *  Đặt false cho cột bắt buộc luôn hiện (VD cột tên, cột thao tác). */
  hideable?: boolean;
  /** Template ô tuỳ biến (avatar+tên, badge, tiến độ, nút…). Ngữ cảnh: $implicit=row, value=row[key]. */
  cell?: TemplateRef<{ $implicit: Record<string, unknown>; value: unknown }>;
}

type Row = Record<string, unknown>;
export type SortDir = 'asc' | 'desc';
/** Một cấp sắp xếp. Danh sách nhiều cấp = sort đa khóa: cấp trên hoà mới xét cấp dưới. */
export interface HrmGridSort { key: string; dir: SortDir; }

/** 1 dòng render khi NHÓM DỮ LIỆU: 'group' = dòng tiêu đề nhóm (toggle+nhãn+đếm), 'row' = dòng dữ liệu lá. */
interface GridRenderItem { kind: string; id: string; depth: number; label?: string; count?: number; path?: string; row?: Row; }

/** Mật độ dòng (theo Astryx Table): auto (theo config toàn cục html[data-density], mặc định)
 *  · compact (dày) · balanced · spacious (thoáng) — truyền cụ thể = override thắng global. */
export type HrmGridDensity = 'auto' | 'compact' | 'balanced' | 'spacious';
/** Kẻ ô (theo Astryx Table): rows (line ngang, mặc định) · columns (line dọc) · grid (cả hai) · none. */
export type HrmGridDividers = 'rows' | 'columns' | 'grid' | 'none';

/** hrm-grid — bảng dữ liệu enterprise config-driven. Bọc nz-table. Toàn token foundation.
 *  v1: columns + data + loading + pagination + size.
 *  v1.1: sortable (per-column), selectable (checkbox + [(selectedKeys)]), striped (zebra).
 *  v1.2: cell template (ô giàu: avatar/badge/nút) + variant 'card' (dòng bo góc, cách nhau — kiểu thẻ dữ liệu).
 *  v1.3 (theo Astryx Table): density + dividers + textOverflow ('truncate' cắt chữ ellipsis — nên đặt width cột).
 *  v1.4: TÙY BIẾN CỘT (opt-in, mặc định OFF ⇒ 41 bảng cũ KHÔNG đổi):
 *    - [reorderable] → grip ⠿ hiện khi hover, kéo đổi thứ tự cột (chuột-only, CDK). Cột ghim không kéo.
 *    - [customizable] → mỗi header có nút ⋯ (Sắp xếp/Ghim trái-phải/Ẩn cột) + nút "Cột" trên bảng để hiện lại cột đã ẩn.
 *    - Sort: single-column, mũi tên GHIM khi active (▲ tăng / ▼ giảm), Enter cycle, aria-sort. Sort do component tự làm.
 *    - Toàn bộ trạng thái (thứ tự/ẩn/ghim/sort) giữ trong SIGNAL NỘI BỘ ⇒ consumer không cần wire gì, tự đồng bộ. In-memory (reload reset). */
@Component({
  selector: 'hrm-grid',
  imports: [
    NzTableModule, NgTemplateOutlet, NzTooltipDirective, NzDropDownModule, NzMenuModule,
    CdkDropList, CdkDrag, CdkDragHandle, TablerIconComponent,
  ],
  template: `
    @if (variant() === 'record') {
      <!-- Bảng bản ghi đơn: mỗi cột thành MỘT DÒNG (nhãn | giá trị) cho một record.
           Tái dùng HrmGridColumn (title=nhãn, cell=ô Table Cells) → xem chi tiết 1 nhân viên/đơn. -->
      <nz-table [nzData]="columns()" [nzShowPagination]="false" [nzSize]="size()" nzTableLayout="fixed">
        <tbody>
          @for (c of columns(); track c.key) {
            <tr>
              <td class="hg-rec-label" [style.width]="labelWidth()">{{ c.title }}</td>
              <td class="hg-rec-value" [style.textAlign]="c.align || 'left'">
                @if (c.cell) {
                  <ng-container [ngTemplateOutlet]="c.cell" [ngTemplateOutletContext]="{ $implicit: recordRow(), value: recordRow()[c.key] }" />
                } @else {
                  {{ recordRow()[c.key] }}
                }
              </td>
            </tr>
          }
        </tbody>
      </nz-table>
    } @else {
    <!-- v1.4 — thanh "Cột" xuất hiện KHI đã tùy biến (ẩn/đổi thứ tự/ghim/đổi rộng) → bảng
         chưa đụng KHÔNG mọc bar. Chứa: hiện lại cột đã ẩn + nút Đặt lại (về mặc định). -->
    @if (customizable() && isDirty()) {
      <div class="hg-bar">
        <button type="button" class="hg-colbtn" nz-dropdown [nzDropdownMenu]="colsMenu" nzTrigger="click"
          [attr.aria-label]="colsBtnLabel()">
          <tabler-icon [icon]="icColumns" [size]="16" />
          @if (colsBtnLabel()) { <span>{{ colsBtnLabel() }}</span> }
          @if (hiddenCount() > 0) { <span class="hg-colbtn-n">{{ hiddenCount() }}</span> }
        </button>
        <nz-dropdown-menu #colsMenu="nzDropdownMenu">
          <ul nz-menu class="hg-menu hg-menu--cols">
            @for (c of pickerColumns(); track c.key) {
              <li nz-menu-item [nzDisabled]="c.hideable === false"
                (click)="toggleHidden(c.key, $event)">
                <tabler-icon [icon]="isHidden(c.key) ? icEyeOff : icEye" [size]="16"
                  [class.hg-mi-off]="isHidden(c.key)" />
                <span>{{ c.title }}</span>
              </li>
            }
            <li nz-menu-divider></li>
            <li nz-menu-item (click)="resetLayout()"><span>{{ resetLabel() }}</span></li>
          </ul>
        </nz-dropdown-menu>
      </div>
    }
    <nz-table
      #t
      [nzData]="displayData()"
      [nzLoading]="loading()"
      [nzBordered]="bordered()"
      [nzSize]="size()"
      [nzShowPagination]="showPagination() && rowGroups().length === 0"
      [nzPageSize]="pageSize()"
      [nzScroll]="scrollObj()"
      [nzTableLayout]="tableLayout()"
      [class.hrm-grid--striped]="striped()">
      <thead>
        @if (headerGroups().hasGroup) {
          <tr class="hg-grouprow">
            @if (selectable()) { <th class="hg-gh hg-gh--empty" nzWidth="48px"></th> }
            @for (cell of headerGroups().cells; track $index) {
              <th [attr.colspan]="cell.span" class="hg-gh" [class.hg-gh--empty]="!cell.grouped">
                @if (cell.grouped) { <span class="hg-gh-t">{{ cell.title }}</span> }
              </th>
            }
          </tr>
        }
        <tr cdkDropList cdkDropListOrientation="horizontal"
          [cdkDropListConnectedTo]="groupConnectedTo()"
          [cdkDropListDisabled]="!reorderable() && groupConnectedTo().length === 0" (cdkDropListDropped)="onColDrop($event)">
          @if (selectable()) {
            <th nzWidth="48px" nzShowCheckbox
              [nzChecked]="allChecked()" [nzIndeterminate]="indeterminate()"
              (nzCheckedChange)="checkAll($event)"></th>
          }
          @for (c of viewColumns(); track c.key) {
            <th cdkDrag [cdkDragData]="c.key" [cdkDragDisabled]="!canDragHeader(c)"
              [style.width]="colWidth(c)" [style.minWidth]="colMinWidth(c)" [style.textAlign]="c.align || 'left'"
              [nzRight]="c.fixed === 'right'" [nzLeft]="c.fixed === 'left'"
              [attr.aria-sort]="ariaSort(c)" [attr.data-key]="c.key">
              <div class="hg-th" [class.hg-th--x]="reorderable() || customizable() || groupConnectedTo().length > 0"
                [class.hg-th--grab]="canDragHeader(c) && !canReorder(c)"
                [style.justifyContent]="c.align === 'right' ? 'flex-end' : (c.align === 'center' ? 'center' : 'flex-start')">
                @if (canDragHeader(c)) {
                  <span class="hg-grip" cdkDragHandle aria-hidden="true"><tabler-icon [icon]="icGrip" [size]="12" /></span>
                }
                @if (c.sortable) {
                  <button type="button" class="hg-lbl hg-lbl--sort" (click)="cycleSort(c.key)"
                    [attr.aria-label]="c.title">
                    <span class="hg-lbl-t">{{ c.title }}</span>
                    @if (sortActive(c.key)) {
                      <tabler-icon class="hg-sort hg-sort--on" [icon]="sortDir(c.key) === 'asc' ? icUp : icDown" [size]="14" />
                      @if (sortPriority(c.key); as pr) { <span class="hg-sort-pri">{{ pr }}</span> }
                    } @else {
                      <tabler-icon class="hg-sort hg-sort--idle" [icon]="icSortIdle" [size]="14" />
                    }
                  </button>
                } @else {
                  <span class="hg-lbl"><span class="hg-lbl-t">{{ c.title }}</span></span>
                }
                @if (customizable() && !isStructural(c)) {
                  <button type="button" class="hg-more" nz-dropdown [nzDropdownMenu]="colMenu"
                    nzTrigger="click" (click)="$event.stopPropagation()" [attr.aria-label]="c.title">
                    <tabler-icon [icon]="icMore" [size]="14" />
                  </button>
                  <nz-dropdown-menu #colMenu="nzDropdownMenu">
                    <!-- Menu ⋯ CHỈ Ghim + Ẩn. Sắp xếp = click tiêu đề (mũi tên hover/ghim);
                         đổi thứ tự = kéo grip ⠿ — không lặp lại trong menu cho gọn. -->
                    <ul nz-menu class="hg-menu">
                      <li nz-menu-item [nzDisabled]="c.fixed === 'left'" (click)="setPin(c.key, 'left')"><tabler-icon [icon]="icPinned" [size]="16" /><span>{{ pinLeftLabel() }}</span></li>
                      <li nz-menu-item [nzDisabled]="c.fixed === 'right'" (click)="setPin(c.key, 'right')"><tabler-icon [icon]="icPinned" [size]="16" /><span>{{ pinRightLabel() }}</span></li>
                      @if (c.fixed) {
                        <li nz-menu-item (click)="setPin(c.key, null)"><tabler-icon [icon]="icPinOff" [size]="16" /><span>{{ pinClearLabel() }}</span></li>
                      }
                      @if (c.hideable !== false) {
                        <li nz-menu-divider></li>
                        <li nz-menu-item (click)="hideCol(c.key)"><tabler-icon [icon]="icEyeOff" [size]="16" /><span>{{ hideLabel() }}</span></li>
                      }
                    </ul>
                  </nz-dropdown-menu>
                }
              </div>
              <!-- Tay kéo độ rộng cột: rê ở cạnh phải header. pointerdown chặn cả sort(click) lẫn grip(drag). -->
              @if (resizable() && !isStructural(c)) {
                <span class="hg-resize" (pointerdown)="startResize($event, c.key)"
                  (click)="$event.stopPropagation()" aria-hidden="true"></span>
              }
            </th>
          }
        </tr>
      </thead>
      <tbody>
        @if (rowGroups().length) {
          <!-- NHÓM DỮ LIỆU: iterate danh sách phẳng (group-header + row) từ groupedRender(); KHÔNG phân trang. -->
          @for (item of groupedRender(); track item.id) {
            @if (item.kind === 'group') {
              <tr class="hg-grp">
                <td [attr.colspan]="colCount()">
                  <button type="button" class="hg-grp-tog" (click)="toggleGroup(item.path!)">
                    <tabler-icon [icon]="isCollapsed(item.path!) ? icChevRight : icChevDown" [size]="14" />
                  </button>
                  <span class="hg-grp-lbl" [style.margin-left.px]="item.depth * 16">{{ item.label }}</span>
                  <span class="hg-grp-n">{{ item.count }}</span>
                </td>
              </tr>
            } @else {
              <tr (click)="rowClick.emit(item.row!)">
                @if (selectable()) {
                  <td nzShowCheckbox [nzChecked]="isChecked(item.row!)"
                    (click)="$event.stopPropagation()"
                    (nzCheckedChange)="checkOne(item.row!, $event)"></td>
                }
                @for (c of viewColumns(); track c.key) {
                  <td [style.textAlign]="c.align || 'left'"
                    [nzRight]="c.fixed === 'right'" [nzLeft]="c.fixed === 'left'">
                    @if (c.cell) {
                      <ng-container [ngTemplateOutlet]="c.cell" [ngTemplateOutletContext]="{ $implicit: item.row!, value: item.row![c.key] }" />
                    } @else if (textOverflow() === 'truncate') {
                      <!-- Ô bị cắt "…" → rê chuột hiện tooltip full nội dung (chỉ khi thật sự tràn). -->
                      <span class="hg-trunc" nz-tooltip [nzTooltipTitle]="truncTip()"
                        (mouseenter)="onTruncEnter($event, item.row![c.key])">{{ item.row![c.key] }}</span>
                    } @else {
                      {{ item.row![c.key] }}
                    }
                  </td>
                }
              </tr>
            }
          }
        } @else {
        @for (row of t.data; track rowKeyOf(row)) {
          <tr (click)="rowClick.emit(row)">
            @if (selectable()) {
              <td nzShowCheckbox [nzChecked]="isChecked(row)"
                (click)="$event.stopPropagation()"
                (nzCheckedChange)="checkOne(row, $event)"></td>
            }
            @for (c of viewColumns(); track c.key) {
              <td [style.textAlign]="c.align || 'left'"
                [nzRight]="c.fixed === 'right'" [nzLeft]="c.fixed === 'left'">
                @if (c.cell) {
                  <ng-container [ngTemplateOutlet]="c.cell" [ngTemplateOutletContext]="{ $implicit: row, value: row[c.key] }" />
                } @else if (textOverflow() === 'truncate') {
                  <!-- Ô bị cắt "…" → rê chuột hiện tooltip full nội dung (chỉ khi thật sự tràn). -->
                  <span class="hg-trunc" nz-tooltip [nzTooltipTitle]="truncTip()"
                    (mouseenter)="onTruncEnter($event, row[c.key])">{{ row[c.key] }}</span>
                } @else {
                  {{ row[c.key] }}
                }
              </td>
            }
          </tr>
        }
        }
      </tbody>
    </nz-table>
    }
  `,
  styles: [`
.hrm-grid--striped tbody tr:nth-child(even) > td { background: var(--bg-surface-subtle); }
.hrm-grid--striped tbody tr:hover > td { background: var(--bg-surface-hover, var(--bg-surface-subtle)); }

/* variant 'card' — dòng bo góc + cách nhau, hover nền nhạt (kiểu thẻ dữ liệu). Toàn token.
   Bỏ khung ngoài mặc định (từng dòng đã tự có viền + bo góc riêng). */
:host(.hrm-grid--card) ::ng-deep .ant-table { background: transparent; border: 0; border-radius: 0; overflow: visible; }
:host(.hrm-grid--card) ::ng-deep .ant-table table { border-collapse: separate; border-spacing: 0 8px; }
:host(.hrm-grid--card) ::ng-deep thead th {
  background: transparent; border: 0 !important; color: var(--text-sub);
  font-size: var(--fs-12); font-weight: 600; text-transform: uppercase; letter-spacing: .03em; padding: 4px 14px;
}
:host(.hrm-grid--card) ::ng-deep tbody > tr > td {
  background: var(--bg-surface); border-top: 1px solid var(--border-sub); border-bottom: 1px solid var(--border-sub);
  padding: 12px 14px; transition: background var(--duration-fast, .15s) var(--ease-out, ease);
}
:host(.hrm-grid--card) ::ng-deep tbody > tr > td:first-child {
  border-left: 1px solid var(--border-sub);
  border-top-left-radius: var(--radius-lg); border-bottom-left-radius: var(--radius-lg);
}
:host(.hrm-grid--card) ::ng-deep tbody > tr > td:last-child {
  border-right: 1px solid var(--border-sub);
  border-top-right-radius: var(--radius-lg); border-bottom-right-radius: var(--radius-lg);
}
:host(.hrm-grid--card) ::ng-deep tbody > tr:hover > td { background: var(--bg-surface-subtle); }

/* v1.3 — density (theo Astryx): cell ăn token --table-cell-pad/--table-font-size.
   Mặc định 'auto' = kế thừa global html[data-density] (config app). Input cụ thể = override var cục bộ. */
:host ::ng-deep .ant-table.ant-table-small .ant-table-tbody > tr > td,
:host ::ng-deep .ant-table.ant-table-small .ant-table-thead > tr > th {
  padding: var(--table-cell-pad, 8px 12px); font-size: var(--table-font-size, 13px);
}
:host([data-density='compact']) { --table-cell-pad: 4px 10px; --table-font-size: var(--fs-12); }
:host([data-density='balanced']) { --table-cell-pad: 8px 12px; --table-font-size: var(--fs-13); }
:host([data-density='spacious']) { --table-cell-pad: 14px 16px; --table-font-size: var(--fs-14); }

/* Header: nền secondary (dịu, tách khỏi body), semibold 600, màu phụ, gạch dưới 1px —
   bỏ vạch dọc phân cột mặc định của ant. Sort icon Tabler do bridge lo (toàn hệ thống). */
:host ::ng-deep .ant-table.ant-table-small .ant-table-thead > tr > th {
  background: var(--bg-surface-subtle); font-weight: 600; color: var(--text-sub);
  border-bottom: 1px solid var(--border-sub);
}

/* Responsive: cột co tới min-width thì bảng hiện thanh cuộn ngang (đặt [minWidth] hoặc width cột). */
:host ::ng-deep .ant-table-content,
:host ::ng-deep .ant-table-body { overflow-x: auto; }
/* Cột ghim (fixed): offset left/right do applyPinOffsets() TỰ tính cộng dồn (đè inline) —
   KHÔNG ép left:0/right:0 ở đây nữa (bug cũ: ghim ≥2 cột đều về 0 ⇒ chồng lên nhau).
   Nền đặc để nội dung cuộn không lộ dưới. */
:host ::ng-deep .ant-table-cell-fix-right,
:host ::ng-deep .ant-table-cell-fix-left { background: var(--bg-surface); z-index: 3; }
/* Header cột ghim: đè rule header 'transparent' (specificity cao) để chữ dưới không lộ qua. */
:host ::ng-deep .ant-table.ant-table-small .ant-table-thead .ant-table-cell-fix-right,
:host ::ng-deep .ant-table.ant-table-small .ant-table-thead .ant-table-cell-fix-left { background: var(--bg-surface-subtle); }
/* Hover dòng — MỘT màu cho MỌI ô, kể cả cột ghim (fixed có nền đặc riêng nên phải đè).
   Đè cả rule mặc định của ant (specificity cao) để cột hành động không lệch màu với dòng. */
:host ::ng-deep .ant-table-tbody > tr:hover > td,
:host ::ng-deep .ant-table-tbody > tr.ant-table-row:hover > td {
  background: var(--table-row-hover-bg, var(--bg-surface-subtle)) !important;
}
:host ::ng-deep .ant-table-thead > tr > th::before { display: none !important; }

/* v1.3 — dividers: rows = mặc định nz (line ngang). */
:host([data-dividers='columns']) ::ng-deep .ant-table.ant-table-small .ant-table-tbody > tr > td { border-bottom: 0; }
:host([data-dividers='columns']) ::ng-deep .ant-table.ant-table-small .ant-table-tbody > tr > td:not(:last-child),
:host([data-dividers='columns']) ::ng-deep .ant-table.ant-table-small .ant-table-thead > tr > th:not(:last-child) { border-right: 1px solid var(--border-sub); }
:host([data-dividers='grid']) ::ng-deep .ant-table.ant-table-small .ant-table-tbody > tr > td:not(:last-child),
:host([data-dividers='grid']) ::ng-deep .ant-table.ant-table-small .ant-table-thead > tr > th:not(:last-child) { border-right: 1px solid var(--border-sub); }
:host([data-dividers='none']) ::ng-deep .ant-table.ant-table-small .ant-table-tbody > tr > td { border-bottom: 0; }

/* v1.3 — textOverflow='truncate': cắt chữ ellipsis (header luôn cắt). Cần width cột để cột không co về 0. */
:host(.hrm-grid--truncate) ::ng-deep .ant-table table { table-layout: fixed; }
:host(.hrm-grid--truncate) ::ng-deep .ant-table-tbody > tr > td,
:host(.hrm-grid--truncate) ::ng-deep .ant-table-thead > tr > th { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.hg-trunc { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* variant 'record' — bảng bản ghi đơn: cột nhãn nền secondary (như header dọc), cột giá trị bình thường. */
:host(.hrm-grid--record) ::ng-deep .hg-rec-label {
  background: var(--bg-surface-subtle); color: var(--text-sub); font-weight: 500;
  vertical-align: middle; white-space: nowrap;
}
:host(.hrm-grid--record) ::ng-deep .hg-rec-value { color: var(--text-body); vertical-align: middle; }
/* Kẻ dọc mảnh giữa nhãn và giá trị cho dễ dò. */
:host(.hrm-grid--record) ::ng-deep .hg-rec-label { border-right: 1px solid var(--border-sub); }

/* ══ v1.4 — Tùy biến cột: header controls (grip + sort ghim + ⋯), thanh "Cột" ══ */
/* Bố cục 1 header: grip | nhãn(+sort) | ⋯. reserve chỗ ⇒ hover KHÔNG làm chữ nhảy. */
.hg-th { display: flex; align-items: center; gap: 2px; min-width: 0; }
/* Header kéo-được-để-nhóm (không grip): cursor grab gợi ý có thể kéo tiêu đề vào rổ nhóm. */
.hg-th--grab { cursor: grab; }
.hg-th--grab:active { cursor: grabbing; }
.hg-lbl {
  display: inline-flex; align-items: center; gap: 4px; min-width: 0;
  border: 0; background: transparent; padding: 0; margin: 0; color: inherit;
  font: inherit; font-weight: inherit; letter-spacing: inherit; text-transform: inherit;
}
.hg-lbl-t { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* ── NHÓM CỘT: hàng tiêu đề nhóm (tầng trên header) ── */
.hg-grouprow > th.hg-gh {
  position: relative; text-align: center; padding: 4px 8px; background: var(--bg-surface-subtle);
  border-bottom: 1px solid var(--border-sub); font-size: var(--fs-12, 12px);
  font-weight: var(--font-semibold, 600); color: var(--text-sub);
}
/* Divider dọc ngăn nhóm: INSET (~60% cao, canh giữa) — đồng bộ header mặc định, KHÔNG full độ cao hàng. */
.hg-grouprow > th.hg-gh:not(.hg-gh--empty):not(:last-child)::after {
  content: ''; position: absolute; inset-inline-end: 0; top: 50%; transform: translateY(-50%);
  height: 60%; width: 1px; background: var(--border-sub);
}
.hg-grouprow > th.hg-gh--empty { background: var(--bg-surface-subtle); }
.hg-gh-t { display: inline-block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 100%; }
.hg-lbl--sort { cursor: pointer; }
.hg-lbl--sort:hover { color: var(--text-strong); }
.hg-lbl--sort:focus-visible { outline: 2px solid var(--primary-focus-ring, var(--primary-base)); outline-offset: 2px; border-radius: var(--radius-sm); }
/* Grip kéo — ĐẶT TUYỆT ĐỐI trong vùng padding TRÁI của ô ⇒ KHÔNG chiếm chỗ inline, nhãn
   header bắt đầu đúng mép content = THẲNG HÀNG với dữ liệu bên dưới (data không có grip).
   Chỉ hiện khi hover. Cursor grab. */
.hg-grip {
  position: absolute; inset-inline-start: 0; top: 50%; transform: translateY(-50%);
  display: inline-grid; place-items: center; width: 12px; height: 18px; color: var(--text-soft);
  cursor: grab; opacity: 0; transition: opacity var(--duration-fast, .15s) var(--ease-out, ease);
}
.hg-grip:active { cursor: grabbing; }
.hg-th--x:hover .hg-grip { opacity: .7; }
/* Mũi tên sort: idle mờ (chỉ hiện khi hover), active GHIM (luôn hiện, màu primary). */
.hg-sort { flex: none; }
/* Icon sort LUÔN hiện mờ ở cột sắp-xếp-được (để user biết bấm được), đậm lên khi hover. */
.hg-sort--idle { opacity: .4; color: var(--text-soft); transition: opacity var(--duration-fast, .15s) var(--ease-out, ease); }
.hg-lbl--sort:hover .hg-sort--idle { opacity: .75; }
.hg-sort--on { opacity: 1; color: var(--primary-base); }
/* Số ưu tiên khi sort ≥2 cấp — badge nhỏ cạnh mũi tên. */
.hg-sort-pri { font-size: var(--fs-10, 10px); font-weight: var(--font-semibold, 600); color: var(--primary-base); line-height: 1; margin-inline-start: 1px; }
/* Nút ⋯ — hiện khi hover header (hoặc khi menu đang mở, ant thêm .ant-dropdown-open). */
.hg-more {
  flex: none; display: inline-grid; place-items: center; width: 20px; height: 20px; margin-inline-start: auto;
  border: 0; background: transparent; border-radius: var(--radius-sm); cursor: pointer; color: var(--text-soft);
  opacity: 0; transition: opacity var(--duration-fast, .15s) var(--ease-out, ease), background var(--duration-fast, .15s) var(--ease-out, ease);
}
.hg-th--x:hover .hg-more, .hg-more.ant-dropdown-open { opacity: 1; }
.hg-more:hover { background: var(--bg-surface); color: var(--text-strong); }
.hg-more:focus-visible { opacity: 1; outline: 2px solid var(--primary-focus-ring, var(--primary-base)); outline-offset: 1px; }

/* Tay kéo độ rộng cột — dải mảnh cạnh phải header. th không-ghim cần position:relative để neo
   (th ghim đã là position:sticky → tự làm chứa tuyệt đối). z-index cao hơn ⋯ để luôn bắt được. */
:host ::ng-deep .ant-table-thead > tr > th:not(.ant-table-cell-fix-left):not(.ant-table-cell-fix-right) { position: relative; }
/* Vùng bắt kéo RỘNG 12px, nằm HẲN trong cell (không thò ra ngoài → không bị th kế đè do stacking
   context; bug cũ: tay 8px thò -3px, pointerdown trúng th thay vì tay). z-index cao để luôn nhận. */
.hg-resize {
  position: absolute; top: 0; inset-inline-end: 0; width: 12px; height: 100%; z-index: 6;
  cursor: col-resize; touch-action: none; user-select: none;
}
/* Đường phân cột LUÔN hiện (mảnh 1px, dịu) để user biết cột kéo được; đậm dần khi hover/kéo. */
.hg-resize::after {
  content: ''; position: absolute; top: 50%; transform: translateY(-50%); inset-inline-end: 3px; width: 1px; height: 45%;
  background: var(--border-sub); transition: background var(--duration-fast, .15s) var(--ease-out, ease);
}
.ant-table-thead > tr > th:hover .hg-resize::after, .hg-resize:hover::after { background: var(--text-soft); width: 2px; }
.hg-resize:active::after { background: var(--primary-base); width: 2px; }

/* Thanh "Cột" trên bảng — phải, gọn. */
.hg-bar { display: flex; justify-content: flex-end; margin-bottom: 8px; }
.hg-colbtn {
  display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 10px;
  border: 1px solid var(--border-sub); background: var(--bg-surface); border-radius: var(--radius-md);
  cursor: pointer; color: var(--text-body); font: inherit; font-size: var(--fs-13);
  transition: border-color var(--duration-fast, .15s) var(--ease-out, ease), background var(--duration-fast, .15s) var(--ease-out, ease);
}
.hg-colbtn:hover { border-color: var(--primary-border); color: var(--text-strong); }
.hg-colbtn:focus-visible { outline: 2px solid var(--primary-focus-ring, var(--primary-base)); outline-offset: 1px; }
.hg-colbtn-n {
  display: inline-grid; place-items: center; min-width: 16px; height: 16px; padding: 0 4px;
  border-radius: var(--radius-full); background: var(--primary-bg-soft); color: var(--primary-base);
  font-size: var(--fs-11); font-weight: 600; line-height: 1;
}

/* Menu ⋯ / "Cột" — icon + chữ, dòng ẩn thì icon mắt-tắt mờ đi. */
:host ::ng-deep .hg-menu li[nz-menu-item] { display: flex; align-items: center; gap: 8px; }
:host ::ng-deep .hg-menu .hg-mi-off { opacity: .5; }

/* ══ NHÓM DỮ LIỆU (row grouping): dòng tiêu đề nhóm = toggle + nhãn (thụt theo cấp) + đếm bản ghi ══ */
.hg-grp { background: var(--bg-surface-subtle); }
.hg-grp > td { padding: 6px 12px; }
.hg-grp-tog { display: inline-grid; place-items: center; width: 20px; height: 20px; border: 0; background: transparent; cursor: pointer; color: var(--text-sub); vertical-align: middle; }
.hg-grp-lbl { font-size: var(--fs-13); font-weight: var(--font-semibold, 600); color: var(--text-strong); }
.hg-grp-n { margin-left: 8px; font-size: var(--fs-12); color: var(--text-sub); background: var(--bg-surface); border: 1px solid var(--border-soft); border-radius: var(--radius-full, 999px); padding: 0 8px; }
  `],
  host: {
    class: 'hrm-grid',
    '[class.hrm-grid--card]': "variant() === 'card'",
    '[class.hrm-grid--record]': "variant() === 'record'",
    '[class.hrm-grid--truncate]': "textOverflow() === 'truncate'",
    '[attr.data-density]': "density() === 'auto' ? null : density()",
    '[attr.data-dividers]': 'dividers()',
  },
})
export class HrmGrid {
  readonly columns = input<HrmGridColumn[]>([]);
  readonly data = input<Row[]>([]);
  readonly loading = input(false);
  readonly bordered = input(false);
  readonly size = input<NzTableSize>('small');
  readonly showPagination = input(true);
  readonly pageSize = input(10);
  readonly scroll = input<{ x?: string; y?: string }>({});
  /** Bề rộng tối thiểu của bảng (VD '900px'). Container hẹp hơn → hiện thanh cuộn ngang.
   *  Tiện lợi hơn scroll — gộp vào nzScroll.x. */
  readonly minWidth = input('');
  /** nzScroll thực dùng: minWidth (nếu có) đè scroll.x. */
  protected readonly scrollObj = computed<{ x?: string; y?: string }>(() => {
    const s = this.scroll();
    const x = this.minWidth() || s.x;
    return x ? { ...s, x } : s;
  });
  readonly striped = input(false);
  readonly selectable = input(false);
  readonly rowKey = input('id');
  /** 'grid' (bảng viền, mặc định) | 'card' (dòng bo góc — kiểu thẻ) | 'record' (bản ghi đơn:
   *  mỗi cột thành 1 dòng nhãn|giá trị cho 1 record — xem chi tiết). */
  readonly variant = input<'grid' | 'card' | 'record'>('grid');
  /** variant='record': bản ghi đơn hiển thị. Bỏ trống → dùng dòng đầu của data(). */
  readonly record = input<Row | null>(null);
  /** variant='record': bề rộng cột nhãn. */
  readonly labelWidth = input('200px');
  /** Mật độ dòng: auto (theo config toàn cục, mặc định) · compact · balanced · spacious. */
  readonly density = input<HrmGridDensity>('auto');
  /** Kẻ ô: rows (ngang, mặc định) · columns (dọc) · grid (cả hai) · none. */
  readonly dividers = input<HrmGridDividers>('rows');
  /** 'wrap' (mặc định) | 'truncate' (cắt chữ ellipsis — nên đặt width cột). */
  readonly textOverflow = input<'wrap' | 'truncate'>('wrap');
  readonly selectedKeys = model<unknown[]>([]);
  readonly rowClick = output<Row>();

  /** NHÓM DỮ LIỆU (row grouping): mỗi phần tử = 1 cấp gom hàng theo cột (nested, multi-level).
   *  RỖNG ⇒ bảng phẳng như hiện tại (ZERO regression, không đụng nhánh cũ). */
  readonly rowGroups = input<HrmRowGroupLevel[]>([]);
  /** NHÓM CỘT (header 2 tầng theo chiều ngang): tầng trên = tiêu đề nhóm span các cột cùng groupId liền kề. */
  readonly columnGroups = input<{ id: string; title: string }[]>([]);
  /** id các cdkDropList (vùng thả cấu hình nhóm) mà header cột nối vào — kéo header thả sang để thêm cấp nhóm. */
  readonly groupConnectedTo = input<string[]>([]);
  /** Định dạng NHÃN nhóm — (key cột, giá trị thô) ⇒ chuỗi hiển thị. Bỏ trống = dùng giá trị thô.
   *  Dùng khi giá trị cột là mã/i18n-key (vd role) cần dịch sang nhãn người đọc trên group-header. */
  readonly groupLabelFormatter = input<((key: string, value: unknown) => string) | null>(null);

  /** v1.4 — kéo đổi thứ tự cột (grip ⠿ hover, chuột-only). MẶC ĐỊNH BẬT cho mọi bảng.
   *  Đặt false cho bảng không muốn (VD bảng 1–2 dòng, bảng con trong tab). */
  readonly reorderable = input(true);
  /** v1.4 — nút ⋯ mỗi header (Ghim/Ẩn cột) + nút "Cột" hiện lại cột đã ẩn. MẶC ĐỊNH BẬT.
   *  Đặt false để tắt tùy biến cột ở bảng cụ thể. */
  readonly customizable = input(true);
  /** v1.4 — kéo cạnh phải header để đổi độ rộng cột. MẶC ĐỊNH BẬT. */
  readonly resizable = input(true);
  /** v1.4 — AUTOSAVE bố cục (thứ tự/ẩn/ghim/rộng/sort) vào localStorage cho lần sau.
   *  Khóa lưu = tableId (nếu đặt) — NÊN đặt id ổn định, duy nhất cho mỗi bảng.
   *  Bỏ trống → tự suy khóa từ đường dẫn trang + danh sách key cột (đủ dùng cho phần lớn ca,
   *  nhưng 2 bảng cùng cột trên cùng trang sẽ đụng khóa ⇒ khi đó hãy đặt tableId). */
  readonly tableId = input('');

  /** Nhãn i18n cho menu (bên gọi cấp; mặc định tiếng Việt để dùng ngay). */
  readonly colsBtnLabel = input('Cột');
  readonly resetLabel = input('Đặt lại mặc định');
  readonly pinLeftLabel = input('Ghim trái');
  readonly pinRightLabel = input('Ghim phải');
  readonly pinClearLabel = input('Bỏ ghim');
  readonly hideLabel = input('Ẩn cột');

  /** Icon (SSOT — Tabler). */
  protected readonly icGrip = IconGripVertical;
  protected readonly icMore = IconDotsVertical;
  protected readonly icSortIdle = IconSelector;
  protected readonly icUp = IconArrowUp;
  protected readonly icDown = IconArrowDown;
  protected readonly icColumns = IconColumns;
  protected readonly icEye = IconEye;
  protected readonly icEyeOff = IconEyeOff;
  protected readonly icPinned = IconPinned;
  protected readonly icPinOff = IconPinnedOff;
  protected readonly icChevDown = IconChevronDown;
  protected readonly icChevRight = IconChevronRight;

  /** ── Trạng thái tùy biến (signal nội bộ) ── */
  /** Thứ tự cột người dùng đã kéo (mảng key). null = theo columns() khai báo. */
  private readonly userOrder = signal<string[] | null>(null);
  /** Cột đang ẩn. */
  /** Khóa các cột đang ẩn (two-way) — toolbar "Cột" bind vào đây để điều khiển ẩn/hiện từ ngoài. */
  readonly hiddenKeys = model<string[]>([]);
  /** Set tra cứu nhanh cho hiddenKeys. */
  private readonly hiddenSet = computed(() => new Set(this.hiddenKeys()));
  /** Ghim cột do người dùng đặt (đè fixed khai báo). */
  private readonly userPin = signal<Readonly<Record<string, 'left' | 'right'>>>({});
  /** Độ rộng (px) người dùng đã kéo, theo key cột. */
  private readonly userWidth = signal<Readonly<Record<string, number>>>({});
  /** Sort hiện tại (single-column). */
  /** Sort ĐA CẤP (two-way) — toolbar/dialog "Cấu hình sắp xếp" bind vào đây; rỗng = không sort.
   *  Click tiêu đề cột = đặt lại về 1 cấp cột đó (sort nhanh). */
  readonly sortLevels = model<HrmGridSort[]>([]);

  private readonly host = inject(ElementRef<HTMLElement>);

  constructor() {
    // NẠP bố cục đã lưu — chạy MỘT LẦN khi columns() sẵn sàng (trước khi vẽ), rồi tự hủy.
    const loader = effect(() => {
      if (!this.columns().length) return;
      this.loadLayout();
      this.loaded = true;
      loader.destroy();
    });
    // AUTOSAVE — mỗi khi bố cục đổi (sau khi đã nạp xong để không ghi đè lúc khởi tạo).
    effect(() => {
      const snap = {
        o: this.userOrder(), h: this.hiddenKeys(),
        p: this.userPin(), w: this.userWidth(), s: this.sortLevels(),
      };
      if (this.loaded) this.saveLayout(snap);
    });
    // Tính offset GHIM cộng dồn sau mỗi lần vẽ (đè inline left:0 của nz ⇒ ghim ≥2 cột không chồng).
    afterRenderEffect(() => {
      this.viewColumns(); this.userWidth(); this.displayData(); // deps → chạy lại khi đổi
      this.applyPinOffsets();
    });
  }
  /** true sau khi đã nạp storage — chặn autosave ghi đè trong lúc khởi tạo. */
  private loaded = false;

  /** Cột thực render: áp thứ tự → ghim (đè fixed) → ẩn → dồn cột ghim về 2 mép.
   *  Khi CẢ HAI opt-in tắt ⇒ trả columns() nguyên vẹn (back-compat tuyệt đối). */
  protected readonly viewColumns = computed<HrmGridColumn[]>(() => {
    const base = this.columns();
    if (!this.reorderable() && !this.customizable()) return base;

    const order = this.userOrder();
    const hidden = this.hiddenSet();
    const pin = this.userPin();

    // 1) áp thứ tự người dùng (key lạ/ mới → đẩy về cuối theo vị trí khai báo)
    let arr = base;
    if (order) {
      const rank = new Map(order.map((k, i) => [k, i]));
      arr = base
        .map((c, i) => ({ c, r: rank.has(c.key) ? rank.get(c.key)! : order.length + i }))
        .sort((a, b) => a.r - b.r)
        .map((x) => x.c);
    }
    // 2) ghim người dùng đè fixed khai báo
    arr = arr.map((c) => {
      const p = pin[c.key];
      return p ? { ...c, fixed: p } : c;
    });
    // 3) ẩn
    arr = arr.filter((c) => !hidden.has(c.key));
    // 4) CHỈ dồn cột NGƯỜI DÙNG ghim ra mép. Cột `fixed` KHAI BÁO giữ NGUYÊN vị trí mảng —
    //    nz vẫn dính nó qua [nzLeft]/[nzRight]. ⇒ bảng chưa ai đụng render Y HỆT bản gốc
    //    (pin rỗng ⇒ grp toàn 1 ⇒ ổn định ⇒ trả base order, fixed khai báo không bị xê dịch).
    const grp = (c: HrmGridColumn) => {
      const p = pin[c.key];
      return p === 'left' ? 0 : p === 'right' ? 2 : 1;
    };
    return arr.map((c, i) => ({ c, i })).sort((a, b) => grp(a.c) - grp(b.c) || a.i - b.i).map((x) => x.c);
  });

  /** Dữ liệu sau sort ĐA CẤP (client-side). nz phân trang trên kết quả này.
   *  So sánh lần lượt từng cấp; cấp trên bằng nhau (0) mới xét cấp dưới. */
  protected readonly displayData = computed<Row[]>(() => {
    const levels = this.sortLevels();
    const data = this.data();
    if (!levels.length) return data;
    const cmpOne = (a: Row, b: Row, key: string): number => {
      const av = a[key], bv = b[key];
      if (typeof av === 'number' && typeof bv === 'number') return av - bv;
      return String(av ?? '').localeCompare(String(bv ?? ''), 'vi');
    };
    return [...data].sort((a, b) => {
      for (const lv of levels) {
        const r = cmpOne(a, b, lv.key) * (lv.dir === 'asc' ? 1 : -1);
        if (r !== 0) return r;
      }
      return 0;
    });
  });

  /** ── NHÓM CỘT (header 2 tầng) ──
   *  Quét viewColumns theo thứ tự hiển thị, gộp các cột cùng groupId LIỀN KỀ thành 1 ô span.
   *  Cột không thuộc nhóm (hoặc groupId lạ) gộp thành ô đệm rỗng. hasGroup=false ⇒ không render tầng nhóm. */
  protected readonly headerGroups = computed<{ cells: { title: string; span: number; grouped: boolean }[]; hasGroup: boolean }>(() => {
    const cols = this.viewColumns();
    const titleById = new Map(this.columnGroups().map((g) => [g.id, g.title]));
    const cells: { title: string; span: number; grouped: boolean }[] = [];
    let hasGroup = false;
    let i = 0;
    while (i < cols.length) {
      const gid = cols[i].groupId;
      if (gid && titleById.has(gid)) {
        let j = i;
        while (j < cols.length && cols[j].groupId === gid) j++;
        cells.push({ title: titleById.get(gid)!, span: j - i, grouped: true });
        hasGroup = true;
        i = j;
      } else {
        let j = i;
        while (j < cols.length && !(cols[j].groupId && titleById.has(cols[j].groupId!))) j++;
        cells.push({ title: '', span: j - i, grouped: false });
        i = j;
      }
    }
    return { cells, hasGroup };
  });

  /** ── NHÓM DỮ LIỆU (row grouping) ── */
  /** Số cột render (gồm cột checkbox nếu selectable) — dùng cho colspan của dòng tiêu đề nhóm. */
  protected readonly colCount = computed(() => this.viewColumns().length + (this.selectable() ? 1 : 0));
  /** Các path nhóm đang thu gọn (đóng). Clone Set khi đổi để signal phát reactive. */
  private readonly collapsed = signal<Set<string>>(new Set());
  protected isCollapsed(path: string): boolean { return this.collapsed().has(path); }
  protected toggleGroup(path: string): void {
    const next = new Set(this.collapsed());
    if (next.has(path)) next.delete(path); else next.add(path);
    this.collapsed.set(next);
  }
  /** Danh sách phẳng để render khi nhóm: xen kẽ dòng tiêu đề nhóm ('group') và dòng dữ liệu lá ('row').
   *  Gom displayData() theo rowGroups() (đệ quy, đa cấp); phụ thuộc collapsed() để thu/mở reactive. */
  protected readonly groupedRender = computed<GridRenderItem[]>(() => {
    const levels = this.rowGroups();
    const collapsedSet = this.collapsed(); // đọc signal → reactive khi thu/mở nhóm
    const data = this.displayData();
    const fmt = this.groupLabelFormatter();
    const out: GridRenderItem[] = [];
    if (!levels.length) return out;
    const build = (rows: Row[], depth: number, prefix: string): void => {
      if (depth >= levels.length) {
        for (const row of rows) {
          out.push({ kind: 'row', id: 'r:' + prefix + ':' + String(this.rowKeyOf(row)), depth, row, path: prefix });
        }
        return;
      }
      const key = levels[depth].key;
      const dir = levels[depth].dir;
      const groups = new Map<string, Row[]>();
      for (const row of rows) {
        const v = String(row[key] ?? '');
        const arr = groups.get(v);
        if (arr) arr.push(row); else groups.set(v, [row]);
      }
      const values = Array.from(groups.keys()).sort(
        (a, b) => a.localeCompare(b, 'vi') * (dir === 'asc' ? 1 : -1),
      );
      for (const v of values) {
        const path = prefix + '/' + v;
        const subset = groups.get(v)!;
        const label = v === '' ? '—' : (fmt ? fmt(key, v) : v);
        out.push({ kind: 'group', id: 'g:' + path, depth, label, count: subset.length, path });
        if (!collapsedSet.has(path)) build(subset, depth + 1, path);
      }
    };
    build(data, 0, '');
    return out;
  });

  protected readonly hiddenCount = computed(() => this.hiddenKeys().length);
  /** Cột hiện trong menu "Cột" (bỏ cột cấu trúc title rỗng — không phải thứ người dùng ẩn/hiện). */
  protected readonly pickerColumns = computed(() => this.columns().filter((c) => c.title && c.title.trim()));

  /** Đã tùy biến gì chưa (thứ tự/ẩn/ghim/rộng) → quyết định hiện thanh "Cột" + nút Đặt lại. */
  protected readonly isDirty = computed(() =>
    this.userOrder() !== null || this.hiddenKeys().length > 0 ||
    Object.keys(this.userPin()).length > 0 || Object.keys(this.userWidth()).length > 0 ||
    this.sortLevels().length > 0,
  );
  /** Độ rộng áp cho cột: ưu tiên px người dùng đã kéo, không thì width khai báo. */
  protected colWidth(c: HrmGridColumn): string | undefined {
    const w = this.userWidth()[c.key];
    return w != null ? w + 'px' : c.width;
  }
  /** min-width CHỈ cho cột người dùng đã kéo → giữ đúng bề rộng; layout 'auto' cho bảng NỚI RA
   *  và CUỘN NGANG (overflow-x:auto sẵn có) thay vì ép cột khác chồng lên nhau. */
  protected colMinWidth(c: HrmGridColumn): string | null {
    const w = this.userWidth()[c.key];
    return w != null ? w + 'px' : null;
  }
  /** table-layout: fixed CHỈ khi cắt-chữ (truncate). Resize giữ 'auto' + min-width (xem colMinWidth). */
  protected readonly tableLayout = computed<'auto' | 'fixed'>(() =>
    this.textOverflow() === 'truncate' ? 'fixed' : 'auto',
  );

  /** ── Sort ── (đa cấp; header hiển thị dir của cột nếu nó nằm trong danh sách cấp) */
  private sortOf(key: string): HrmGridSort | undefined { return this.sortLevels().find((l) => l.key === key); }
  protected sortActive(key: string): boolean { return !!this.sortOf(key); }
  protected sortDir(key: string): SortDir | null { return this.sortOf(key)?.dir ?? null; }
  /** Số ưu tiên (1,2,3…) khi sort ≥2 cấp — hiện cạnh mũi tên. 0 = không hiện (0/1 cấp). */
  protected sortPriority(key: string): number {
    const ls = this.sortLevels();
    if (ls.length < 2) return 0;
    const i = ls.findIndex((l) => l.key === key);
    return i < 0 ? 0 : i + 1;
  }
  /** Click tiêu đề = SORT NHANH: đặt lại về DUY NHẤT 1 cấp cột đó, cycle tăng→giảm→bỏ. */
  protected cycleSort(key: string): void {
    const cur = this.sortLevels();
    const only = cur.length === 1 && cur[0].key === key ? cur[0] : null;
    if (!only) { this.sortLevels.set([{ key, dir: 'asc' }]); return; }
    if (only.dir === 'asc') { this.sortLevels.set([{ key, dir: 'desc' }]); return; }
    this.sortLevels.set([]);
  }
  protected ariaSort(c: HrmGridColumn): 'ascending' | 'descending' | 'none' | null {
    if (!c.sortable) return null;
    const d = this.sortDir(c.key);
    return d === 'asc' ? 'ascending' : d === 'desc' ? 'descending' : 'none';
  }

  /** ── Ghim / ẩn / thứ tự ── */
  /** Cột "cấu trúc" (title rỗng — VD cột thao tác/nút) KHÔNG cho kéo/ghim/ẩn: đưa nó vào
   *  tùy biến chỉ gây rối (grip trên ô trống, dòng trắng trong picker). */
  protected isStructural(c: HrmGridColumn): boolean { return !c.title || !c.title.trim(); }
  protected canReorder(c: HrmGridColumn): boolean { return this.reorderable() && !c.fixed && !this.isStructural(c); }
  /** Header KÉO ĐƯỢC khi: cho đổi thứ tự (reorderable) HOẶC đang nối rổ nhóm (groupConnectedTo) —
   *  để kéo tiêu đề vào rổ nhóm dù đã tắt reorder/grip. Bỏ cột cố định + cột cấu trúc. */
  protected canDragHeader(c: HrmGridColumn): boolean {
    return (this.reorderable() || this.groupConnectedTo().length > 0) && !c.fixed && !this.isStructural(c);
  }
  protected setPin(key: string, side: 'left' | 'right' | null): void {
    const next = { ...this.userPin() };
    if (side) next[key] = side; else delete next[key];
    this.userPin.set(next);
  }
  protected isHidden(key: string): boolean { return this.hiddenSet().has(key); }
  protected hideCol(key: string): void {
    this.hiddenKeys.update((a) => (a.includes(key) ? a : [...a, key]));
  }
  protected toggleHidden(key: string, e?: Event): void {
    e?.stopPropagation();
    this.hiddenKeys.update((a) => (a.includes(key) ? a.filter((k) => k !== key) : [...a, key]));
  }
  protected resetLayout(): void {
    this.userOrder.set(null); this.hiddenKeys.set([]);
    this.userPin.set({}); this.userWidth.set({}); this.sortLevels.set([]);
    this.clearLayout();
  }
  protected onColDrop(e: CdkDragDrop<unknown>): void {
    if (!this.reorderable()) return; // reorder tắt ⇒ header chỉ kéo-vào-rổ, KHÔNG đổi thứ tự nội bảng
    if (e.previousIndex === e.currentIndex) return;
    const keys = this.viewColumns().map((c) => c.key);
    moveItemInArray(keys, e.previousIndex, e.currentIndex);
    this.userOrder.set(keys);
  }

  /** ── Kéo độ rộng cột ── setPointerCapture ⇒ mọi pointermove/up sau đó về ĐÚNG tay kéo dù
   *  con trỏ rời phần tử — chắc hơn nghe trên document, không lệ thuộc bubble/CDK. */
  protected startResize(e: PointerEvent, key: string): void {
    e.preventDefault(); e.stopPropagation();
    const handle = e.currentTarget as HTMLElement;
    const th = handle.closest('th') as HTMLElement | null;
    if (!th) return;
    const startX = e.clientX;
    const startW = Math.round(th.getBoundingClientRect().width);
    try { handle.setPointerCapture(e.pointerId); } catch { /* trình duyệt cũ */ }
    const move = (ev: PointerEvent) => {
      const w = Math.max(60, startW + (ev.clientX - startX));
      this.userWidth.update((m) => ({ ...m, [key]: Math.round(w) }));
    };
    const up = () => {
      handle.removeEventListener('pointermove', move);
      handle.removeEventListener('pointerup', up);
      handle.removeEventListener('pointercancel', up);
      try { handle.releasePointerCapture(e.pointerId); } catch { /* đã nhả */ }
    };
    handle.addEventListener('pointermove', move);
    handle.addEventListener('pointerup', up);
    handle.addEventListener('pointercancel', up);
  }

  /** ── Ghim: offset cộng dồn ── nz đặt inline left:0 cho MỌI cột ghim (không cộng dồn khi
   *  bảng không ở chế độ scroll) ⇒ ghim ≥2 cột chồng nhau. Tự đo bề rộng header rồi ghi
   *  left/right cộng dồn lên th + mọi td cùng cột (đè inline của nz). */
  private applyPinOffsets(): void {
    const root = this.host.nativeElement as HTMLElement;
    const headRow = root.querySelector('.ant-table-thead > tr') as HTMLElement | null;
    if (!headRow) return;
    const ths = Array.from(headRow.children) as HTMLElement[];
    const cols = this.viewColumns();
    const lead = ths.length - cols.length; // th đứng trước cột (checkbox chọn) nếu có
    if (lead < 0) return;
    const rows = Array.from(root.querySelectorAll('.ant-table-tbody > tr')) as HTMLElement[];
    const setSide = (colIdx: number, side: 'left' | 'right', px: number) => {
      const cellIdx = lead + colIdx;
      const other = side === 'left' ? 'right' : 'left';
      const put = (el?: HTMLElement) => { if (el) { el.style[side] = px + 'px'; el.style[other] = ''; } };
      put(ths[cellIdx]);
      for (const r of rows) put(r.children[cellIdx] as HTMLElement);
    };
    let accL = 0;
    for (let i = 0; i < cols.length; i++) {
      if (cols[i].fixed === 'left') { setSide(i, 'left', accL); accL += ths[lead + i]?.getBoundingClientRect().width ?? 0; }
    }
    let accR = 0;
    for (let i = cols.length - 1; i >= 0; i--) {
      if (cols[i].fixed === 'right') { setSide(i, 'right', accR); accR += ths[lead + i]?.getBoundingClientRect().width ?? 0; }
    }
  }

  /** ── Autosave (localStorage) ── */
  private storageKey(): string {
    const id = this.tableId();
    if (id) return 'hg:layout:' + id;
    const path = typeof location !== 'undefined' ? location.pathname : '';
    return 'hg:layout:' + path + '|' + this.columns().map((c) => c.key).join(',');
  }
  private loadLayout(): void {
    if (typeof localStorage === 'undefined') return;
    try {
      const raw = localStorage.getItem(this.storageKey());
      if (!raw) return;
      const d = JSON.parse(raw) as { o?: string[] | null; h?: string[]; p?: Record<string, 'left' | 'right'>; w?: Record<string, number>; s?: HrmGridSort[] | { key: string; dir: SortDir } | null };
      if (d.o) this.userOrder.set(d.o);
      if (d.h?.length) this.hiddenKeys.set(d.h);
      if (d.p && Object.keys(d.p).length) this.userPin.set(d.p);
      if (d.w && Object.keys(d.w).length) this.userWidth.set(d.w);
      // Tương thích cả bản cũ (object đơn) lẫn bản mới (mảng cấp).
      if (Array.isArray(d.s)) { if (d.s.length) this.sortLevels.set(d.s); }
      else if (d.s) this.sortLevels.set([d.s]);
    } catch { /* JSON hỏng / storage chặn → bỏ qua, dùng mặc định */ }
  }
  private saveLayout(snap: { o: string[] | null; h: string[]; p: Record<string, 'left' | 'right'>; w: Record<string, number>; s: HrmGridSort[] }): void {
    if (typeof localStorage === 'undefined') return;
    const empty = !snap.o && !snap.h.length && !Object.keys(snap.p).length && !Object.keys(snap.w).length && !snap.s.length;
    try {
      if (empty) localStorage.removeItem(this.storageKey());
      else localStorage.setItem(this.storageKey(), JSON.stringify(snap));
    } catch { /* quota / chặn → bỏ qua */ }
  }
  private clearLayout(): void {
    if (typeof localStorage === 'undefined') return;
    try { localStorage.removeItem(this.storageKey()); } catch { /* bỏ qua */ }
  }

  /** Tooltip cho ô đang rê chuột — chỉ set khi ô THẬT SỰ bị cắt (scrollWidth > clientWidth). */
  protected readonly truncTip = signal<string | null>(null);

  protected onTruncEnter(e: Event, value: unknown): void {
    const el = e.target as HTMLElement;
    this.truncTip.set(el.scrollWidth > el.clientWidth ? String(value ?? '') : null);
  }

  /** Bản ghi hiển thị cho variant='record': record() nếu có, không thì dòng đầu của data(). */
  protected readonly recordRow = computed<Row>(() => this.record() ?? this.data()[0] ?? {});

  protected rowKeyOf(row: Row): unknown { return row[this.rowKey()]; }
  protected isChecked(row: Row): boolean { return this.selectedKeys().includes(this.rowKeyOf(row)); }

  protected checkOne(row: Row, checked: boolean): void {
    const k = this.rowKeyOf(row);
    const cur = this.selectedKeys();
    this.selectedKeys.set(checked ? [...cur, k] : cur.filter((x) => x !== k));
  }

  protected checkAll(checked: boolean): void {
    this.selectedKeys.set(checked ? this.data().map((r) => this.rowKeyOf(r)) : []);
  }

  protected readonly allChecked = computed(() => {
    const d = this.data();
    return d.length > 0 && d.every((r) => this.selectedKeys().includes(this.rowKeyOf(r)));
  });

  protected readonly indeterminate = computed(() => {
    const some = this.data().some((r) => this.selectedKeys().includes(this.rowKeyOf(r)));
    return some && !this.allChecked();
  });
}
